import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class UsersService { constructor(private readonly prisma: PrismaService) {} findAll() { return this.prisma.user.findMany({ select: { id: true, name: true, email: true, status: true, organizationId: true, departmentId: true, createdAt: true, lastLoginAt: true }, orderBy: { createdAt: 'desc' } }); } }
